def preserve_saved_kaleidescape_movies(apps, schema_editor):
    del schema_editor
    Movie = apps.get_model("posters", "Movie")
    for movie in Movie.objects.filter(source="kaleidescape").iterator():
        movie.source = "manual"
        movie.source_key = f"legacy-kaleidescape-{movie.pk}"
        movie.save(update_fields=["source", "source_key"])


def preserve_current_playback_poster(apps, schema_editor):
    del schema_editor
    PlaybackSnapshot = apps.get_model("posters", "PlaybackSnapshot")
    PosterAsset = apps.get_model("posters", "PosterAsset")
    for snapshot in PlaybackSnapshot.objects.exclude(poster_id=None).iterator():
        poster = PosterAsset.objects.filter(pk=snapshot.poster_id).first()
        if poster:
            snapshot.poster_path = poster.path
            snapshot.save(update_fields=["poster_path"])


